menv python -c "
from hera.analysis import open_run
import numpy as np, glob
for d in sorted(glob.glob('data/[0-9]*')):
    try:
        run = open_run(d)
    except Exception as e:
        print(d, 'open failed:', e); continue
    line = d + '  '
    seen = set()
    for c in run.cols:
        if c in seen: continue
        seen.add(c)
        if c.endswith('_volt') or 'curr' in c:
            idx = run.col_indices(c)
            x = run.col_at(idx[-1])  # last occurrence = recorded fp column
            if c.endswith('_volt'):
                line += f'{c}[{x[0]:+.2f}->{x[-1]:+.2f}] '
            else:
                line += f'{c}(max {np.abs(x).max():.2e}) '
    print(line, 'int:', run.interrupted, 'rows:', run.nrows if hasattr(run,'nrows') else len(x))
"

